  border-radius: 50%;
  background: var(--color-brand);
}

.timeline-year {
  font-weight: 800;
  color: var(--color-brand);
}

.cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
